#include "c1.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static unsigned groups;
#define TEST(f) do{f();++groups;puts("PASS "#f);}while(0)
static C1 *instance(void){C1 *c=calloc(1,sizeof(C1Audio));assert(c&&c1_init(c,16000));c1_bind(c,&((C1Audio*)c)->engine,1);return c;}
static void process(C1 *c,unsigned n){float x[128],l[128],r[128];for(unsigned k=0;k<128;++k)x[k]=.1f*sinf(k*.13f);while(n){unsigned b=n>128?128:n;c1_process(c,x,NULL,l,r,b,NULL,0);for(unsigned k=0;k<b;++k)assert(isfinite(l[k])&&isfinite(r[k]));n-=b;}}
static void test_c0_equivalence(void){C1 *c=instance();GAudio *a=calloc(1,sizeof(*a));assert(a&&ghost_audio_init(a,16000));GConfig g=ghost_defaults();g.enabled=1;g.density=8;g.probability=1;g.destination[0]=(GDestination){1,1,1,10,90,1,0};g.destination[1]=(GDestination){1,1,1,0,.5f,1,0};assert(ghost_configure(&a->ghost,&g));C1State s=c->state;s.event=g;for(unsigned d=0;d<4;++d)s.random[d]=g.destination[d];assert(c1_apply(c,&s));
 for(unsigned k=0;k<32000;++k){float x=.2f*sinf(k*.09f),al,ar,bl,br;ghost_audio_process(a,&x,NULL,&al,&ar,1,NULL,0);c1_process(c,&x,NULL,&bl,&br,1,NULL,0);assert(al==bl&&ar==br);}free(a);free(c);}
static void test_eight_motion_types(void){for(unsigned type=0;type<8;++type){C1 *c=instance();c->state.source[0].type=type;c->state.source[0].rate=50;float min=2,max=-1;c->energy=.2f;
 for(unsigned k=0;k<16000;k+=32){float x=c1_motion(c,0,k,k/8000.,k%800==0);assert(x>=0&&x<=1);min=fminf(min,x);max=fmaxf(max,x);}if(type!=M_HOLD)assert(max>min);free(c);}}
static void test_walk_hold_repeat(void){C1 *c=instance();MConfig *m=&c->state.source[0];m->type=M_WALK;m->rate=5;for(unsigned k=0;k<100000;k+=32){float x=c1_motion(c,0,k,0,0);assert(x>=0&&x<=1);}m->hold=1;float held=c1_motion(c,0,100000,0,0);assert(c1_motion(c,0,200000,0,0)==held);
 memset(c->source,0,sizeof c->source);m->hold=0;m->type=M_REPEAT;m->rate=10;float a[8];for(unsigned i=0;i<16;++i){float x=c1_motion(c,0,i*160,0,0);if(i<8)a[i]=x;else assert(x==a[i%8]);}free(c);}
static void test_stream_independence(void){C1 *a=instance(),*b=instance();a->state.source[3].type=b->state.source[3].type=M_WALK;for(unsigned k=0;k<160000;k+=32){c1_motion(a,0,k,0,0);assert(c1_motion(a,3,k,0,0)==c1_motion(b,3,k,0,0));}free(a);free(b);}
static void test_dice_and_locks(void){C1 *c=instance();c->state.locked[C1_PITCH]=1;c->state.manual[C1_PITCH]=7;C1State before=c->state;c1_dice(c,1);assert(c->state.manual[C1_PITCH]==7&&!(c->dice_mask&(1u<<C1_PITCH)));assert(!c->state.motion&&!c->state.event.enabled);assert(!memcmp(before.manual,c->state.manual,sizeof before.manual));
 c->state.route[2].source=0;c->state.locked[2]=1;MConfig source=c->state.source[0];c1_dice(c,2);assert(!memcmp(&source,&c->state.source[0],sizeof source));assert(!c->state.motion);free(c);}
static void test_buffer_bypass(void){C1 *c=instance();c1_set(c,P_CAPTURE,1);process(c,1000);c1_set(c,P_CAPTURE,1);process(c,1);int bank=c->engine->r.captured;assert(bank>=0);c1_set(c,P_BUFFER,0);c1_dice(c,1);assert(!c->dice_mask);assert(c->engine->r.captured==bank);
 c1_set(c,P_FREEZE,1);process(c,100);assert(c->engine->r.base.freeze);free(c);}
static void test_chaos_rests_clean_priority(void){C1 *c=instance();C1State s=c->state;s.event.enabled=1;s.event.density=16;s.event.probability=1;s.event.beat_sync=0;s.event.distance=5;s.event.duration_ms=100;s.motion=1;s.chaos_on=1;s.chaos=1;assert(c1_apply(c,&s));unsigned active=0;for(unsigned k=0;k<16000;++k){process(c,1);active+=c->clock.active;}assert(active<8000);assert(c->state.manual[C1_MIX]==1);
 c1_set(c,P_CLEAN,1);c1_set(c,P_BUFFER_DICE,1);process(c,512);assert(!c->state.motion&&!c->state.event.enabled&&!c->state.listen&&c->depth==0&&c->status==S_CLEAN);free(c);}
static void test_manual_priority(void){C1 *c=instance();C1State s=c->state;s.motion=1;s.route[0].enabled=1;s.route[0].minimum=200;s.route[0].maximum=300;s.manual[C1_GATE]=1;assert(c1_apply(c,&s));process(c,2000);c1_set(c,P_LENGTH,35);process(c,512);assert(c->engine->r.base.ms==35&&c->state.manual[0]==35);free(c);}
static void test_state_roundtrip_atomic(void){C1 *a=instance(),*b=instance();C1State s=a->state;s.event.distance=.3;s.motion=1;s.route[5].enabled=1;s.source[3].type=M_WALK;assert(c1_apply(a,&s));unsigned char data[4096],again[4096];size_t n=c1_save(a,data,sizeof data);assert(n<sizeof data);assert(c1_load(b,data,n));assert(b->state.event.distance==.3);assert(c1_save(b,again,sizeof again)==n&&!memcmp(data,again,n));
 C1State before=b->state;data[24]^=1;assert(!c1_load(b,data,n)&&!memcmp(&before,&b->state,sizeof before));for(unsigned len=0;len<32;++len)assert(!c1_load(b,data,len));free(a);free(b);}
static void test_parameter_validation(void){C1 *c=instance();for(unsigned i=0;i<P_COUNT;++i){assert(!c1_set(c,i,NAN));assert(!c1_set(c,i,INFINITY));}assert(!c1_set(c,P_DEST,12));assert(!c1_set(c,P_STATUS,0));assert(c1_set(c,P_MOTION,1));C1State before=c->state;C1State invalid=before;invalid.route[1].minimum=NAN;assert(!c1_apply(c,&invalid));assert(!memcmp(&before,&c->state,sizeof before));free(c);}
static void test_listen_latency(void){C1 *c=instance();c1_set(c,P_LISTEN,1);c1_set(c,P_SPACING,100);float zero[128]={0},one[128];for(unsigned k=0;k<128;++k)one[k]=.5f;c1_process(c,zero,NULL,NULL,NULL,2048/16,NULL,0);process(c,2048);c1_process(c,one,NULL,NULL,NULL,128,NULL,0);assert(c->onsets>0);unsigned n=c->onsets;c1_process(c,one,NULL,NULL,NULL,128,NULL,0);assert(c->onsets==n);free(c);}
static void test_rapid_presets_tempo_transport(void){C1 *c=instance();unsigned char bytes[4096];size_t n=c1_save(c,bytes,sizeof bytes);for(unsigned i=0;i<1000;++i){assert(c1_load(c,bytes,n));assert(ghost_clock(&c->clock,i%2?65:200,i%3!=0,1,i*.25));process(c,64);}free(c);}
static void test_audio_block_invariance(void){C1 *a=instance(),*b=instance();C1State s=a->state;s.event.enabled=1;s.motion=1;s.route[4].enabled=1;s.source[4].sync=1;s.source[4].rate=.25;assert(c1_apply(a,&s)&&c1_apply(b,&s));float in[2048],al[2048],ar[2048],bl[2048],br[2048];for(unsigned k=0;k<2048;++k)in[k]=.1f*sinf(k*.1f);c1_process(a,in,NULL,al,ar,2048,NULL,0);unsigned p=0;while(p<2048){unsigned n=p%77+1;if(n>2048-p)n=2048-p;c1_process(b,in+p,NULL,bl+p,br+p,n,NULL,0);p+=n;}assert(!memcmp(al,bl,sizeof al)&&!memcmp(ar,br,sizeof ar));free(a);free(b);}
static void test_rates_stress(void){const unsigned rates[]={16000,44100,48000,96000};for(unsigned j=0;j<4;++j){C1 *c=instance();c1_init(c,rates[j]);c1_bind(c,&((C1Audio*)c)->engine,1);C1State s=c->state;s.event.enabled=s.motion=s.chaos_on=s.listen=1;s.chaos=1;for(unsigned d=0;d<12;++d){s.random[d].enabled=1;s.route[d].enabled=1;}assert(c1_apply(c,&s));for(unsigned k=0;k<2000;++k){if(k%11==0)c1_dice(c,k%3);if(k%97==0)c1_set(c,P_CLEAN,1);process(c,128);}free(c);}}
static void test_motion_release_and_capture_status(void){C1 *c=instance();C1State s=c->state;s.motion=1;s.route[C1_BEND].enabled=1;s.source[7].type=M_SINE;s.source[7].rate=100;s.route[C1_BEND].source=7;assert(c1_apply(c,&s));process(c,1000);float before=c->route_value[C1_BEND];c1_set(c,P_MOTION,0);process(c,1);assert(fabsf(c->route_value[C1_BEND]-before)<1);process(c,200);assert(fabsf(c->route_value[C1_BEND])<.001f);c1_set(c,P_CAPTURE,1);process(c,1);assert(c->status==S_CAPTURE);process(c,100);assert(c->status==S_CAPTURE);process(c,2000);assert(c->status==S_IDLE);free(c);}
static void test_c0_migration(void){GAudio *a=calloc(1,sizeof(*a));C1 *c=instance();assert(ghost_audio_init(a,16000));GConfig g=ghost_defaults();g.enabled=1;g.seed=481;assert(ghost_configure(&a->ghost,&g));assert(ghost_audio_mix(a,.37f));assert(c1_import_c0(c,a));assert(c->state.event.seed==481&&c->state.event.enabled&&!c->state.motion&&c->state.manual[C1_MIX]==.37f&&!c->state.manual[C1_GATE]);free(a);free(c);}
static void test_long_running(void){C1 *c=instance();C1State s=c->state;s.event.enabled=s.motion=s.listen=s.chaos_on=1;s.chaos=1;for(unsigned i=0;i<12;++i)s.random[i].enabled=s.route[i].enabled=1;assert(c1_apply(c,&s));/* ten minutes simulated at16k, no wall-clock waiting */for(unsigned k=0;k<75000;++k){if(k%997==0)c1_dice(c,k%3);process(c,128);}assert(c->clock.sample==9600000);free(c);}
int main(void){TEST(test_motion_release_and_capture_status);TEST(test_c0_migration);TEST(test_long_running);TEST(test_c0_equivalence);TEST(test_eight_motion_types);TEST(test_walk_hold_repeat);TEST(test_stream_independence);TEST(test_dice_and_locks);TEST(test_buffer_bypass);TEST(test_chaos_rests_clean_priority);TEST(test_manual_priority);TEST(test_state_roundtrip_atomic);TEST(test_parameter_validation);TEST(test_listen_latency);TEST(test_rapid_presets_tempo_transport);TEST(test_audio_block_invariance);TEST(test_rates_stress);printf("%u C1 test groups passed\n",groups);return 0;}
